CREATE TABLE "usuarios" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" text NOT NULL,
  "correo" text UNIQUE NOT NULL,
  "password_hash" text NOT NULL,
  "rol" text NOT NULL DEFAULT 'estudiante'
);

CREATE TABLE "edificios" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" text NOT NULL
);

CREATE TABLE "categorias" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" text UNIQUE NOT NULL
);

CREATE TABLE "tipos_espacio" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "categoria_id" integer NOT NULL,
  "nombre" text UNIQUE NOT NULL,
  "anticipacion_dias" integer NOT NULL DEFAULT 3,
  "max_horas" integer NOT NULL DEFAULT 2
);

CREATE TABLE "espacios" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "edificio_id" integer NOT NULL,
  "tipo_id" integer NOT NULL,
  "nombre" text NOT NULL,
  "piso" integer,
  "capacidad" integer NOT NULL,
  "accesible" boolean NOT NULL DEFAULT false,
  "notas_accesibilidad" text,
  "activo" boolean NOT NULL DEFAULT true
);

CREATE TABLE "horarios_espacio" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "espacio_id" integer NOT NULL,
  "dia_semana" integer NOT NULL,
  "apertura" time NOT NULL,
  "cierre" time NOT NULL
);

CREATE TABLE "cierres_espacio" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "espacio_id" integer NOT NULL,
  "inicio" timestamp NOT NULL,
  "fin" timestamp NOT NULL,
  "motivo" text
);

CREATE TABLE "modulos" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "espacio_id" integer NOT NULL,
  "nombre" text NOT NULL,
  "capacidad" integer NOT NULL
);

CREATE TABLE "recursos" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" text UNIQUE NOT NULL
);

CREATE TABLE "espacio_recursos" (
  "espacio_id" integer NOT NULL,
  "recurso_id" integer NOT NULL,
  "cantidad" integer NOT NULL DEFAULT 1,
  PRIMARY KEY ("espacio_id", "recurso_id")
);

CREATE TABLE "reservas" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "usuario_id" integer NOT NULL,
  "espacio_id" integer NOT NULL,
  "inicio" timestamp NOT NULL,
  "fin" timestamp NOT NULL,
  "motivo" text,
  "num_asistentes" integer,
  "estado" text NOT NULL DEFAULT 'confirmada',
  "creada" timestamp NOT NULL DEFAULT (now())
);

CREATE TABLE "reserva_modulos" (
  "reserva_id" integer NOT NULL,
  "modulo_id" integer NOT NULL,
  "inicio" timestamp NOT NULL,
  "fin" timestamp NOT NULL,
  PRIMARY KEY ("reserva_id", "modulo_id")
);

CREATE TABLE "notificaciones" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "reserva_id" integer NOT NULL,
  "destinatario" text NOT NULL,
  "tipo" text NOT NULL,
  "estado" text NOT NULL DEFAULT 'pendiente',
  "intentos" integer NOT NULL DEFAULT 0,
  "error" text,
  "creada" timestamp NOT NULL DEFAULT (now()),
  "enviada_en" timestamp
);

COMMENT ON COLUMN "usuarios"."rol" IS 'estudiante | docente | administrativo | admin';

COMMENT ON COLUMN "categorias"."nombre" IS 'academico | deportivo | recreativo | eventos';

COMMENT ON COLUMN "espacios"."accesible" IS 'movilidad reducida';

COMMENT ON COLUMN "horarios_espacio"."dia_semana" IS '1=lunes ... 7=domingo';

COMMENT ON COLUMN "cierres_espacio"."motivo" IS 'mantenimiento, evento institucional, festivo';

COMMENT ON COLUMN "modulos"."nombre" IS 'Todo espacio tiene al menos uno; "Espacio completo" si no tiene módulos reales';

COMMENT ON COLUMN "reservas"."estado" IS 'confirmada | cancelada';

COMMENT ON COLUMN "reserva_modulos"."fin" IS 'EXCLUDE gist (modulo_id =, tsrange(inicio, fin) &&) evita cruces';

COMMENT ON COLUMN "notificaciones"."tipo" IS 'confirmacion | cancelacion | recordatorio';

COMMENT ON COLUMN "notificaciones"."estado" IS 'pendiente | enviada | fallida';

ALTER TABLE "tipos_espacio" ADD FOREIGN KEY ("categoria_id") REFERENCES "categorias" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "espacios" ADD FOREIGN KEY ("edificio_id") REFERENCES "edificios" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "espacios" ADD FOREIGN KEY ("tipo_id") REFERENCES "tipos_espacio" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "horarios_espacio" ADD FOREIGN KEY ("espacio_id") REFERENCES "espacios" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "cierres_espacio" ADD FOREIGN KEY ("espacio_id") REFERENCES "espacios" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "modulos" ADD FOREIGN KEY ("espacio_id") REFERENCES "espacios" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "espacio_recursos" ADD FOREIGN KEY ("espacio_id") REFERENCES "espacios" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "espacio_recursos" ADD FOREIGN KEY ("recurso_id") REFERENCES "recursos" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "reservas" ADD FOREIGN KEY ("usuario_id") REFERENCES "usuarios" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "reservas" ADD FOREIGN KEY ("espacio_id") REFERENCES "espacios" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "reserva_modulos" ADD FOREIGN KEY ("reserva_id") REFERENCES "reservas" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "reserva_modulos" ADD FOREIGN KEY ("modulo_id") REFERENCES "modulos" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "notificaciones" ADD FOREIGN KEY ("reserva_id") REFERENCES "reservas" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;
